import { parseAst } from "rollup/parseAst";
import type { Plugin } from "vite";
import rollupSeismic from "../../src/seismic";
import { servicenowSeismicPlugin, withBase } from "../../src/vite/seismic";
import { UXASSET_EXTERNAL_PREFIX } from "../../src/utils/constants";
import { isolateExternalImports } from "../../src/utils/isolate-external-imports";

type PluginRecord = Record<string, any>;

const IMPORTER = "/project/src/main.js";

/**
 * The plugin parses via `this.parse`, which the host supplies (Rollup on Vite
 * 6/7, Rolldown on Vite 8). Rollup's parser stands in for it here.
 */
const parse = (code: string) => parseAst(code);

const transform = (plugin: Plugin, code: string, id = IMPORTER) =>
  (plugin as PluginRecord).transform.call({ parse }, code, id);

const configure = (plugin: Plugin, command: "build" | "serve", base: string) =>
  (plugin as PluginRecord).configResolved({ command, base });

const resolveId = (plugin: Plugin, source: string) =>
  (plugin as PluginRecord).resolveId.call({}, source, IMPORTER, {
    isEntry: false,
  });

describe("servicenowSeismicPlugin", () => {
  test("keeps the seismic name and runs before vite's own resolution", () => {
    const plugin = servicenowSeismicPlugin() as PluginRecord;
    expect(plugin.name).toBe("seismic");
    expect(plugin.enforce).toBe("pre");
    // no `apply`: it must run in build as well as dev
    expect(plugin.apply).toBeUndefined();
  });

  describe("rewriting the import", () => {
    test("rewrites an `assert` uxasset external and drops the clause", () => {
      const result = transform(
        servicenowSeismicPlugin(),
        'import a from "@servicenow/now-button" assert { external: "uxasset" };\n',
      );
      expect(result.code).toBe(
        'import a from "/uxasset/externals/@servicenow/now-button/index.jsdbx";\n',
      );
    });

    test("rewrites a `with` uxasset external and drops the clause", () => {
      const result = transform(
        servicenowSeismicPlugin(),
        'import a from "@devsnc/library-uxf" with { external: "uxasset" };\n',
      );
      expect(result.code).toBe(
        'import a from "/uxasset/externals/@devsnc/library-uxf/index.jsdbx";\n',
      );
    });

    test("rewrites a re-export", () => {
      const result = transform(
        servicenowSeismicPlugin(),
        'export * from "lodash" assert { external: "uxasset" };\n',
      );
      expect(result.code).toBe(
        'export * from "/uxasset/externals/lodash/index.jsdbx";\n',
      );
    });

    test("rewrites a named re-export", () => {
      const result = transform(
        servicenowSeismicPlugin(),
        'export { a } from "pkg" assert { external: "uxasset" };\n',
      );
      expect(result.code).toBe(
        'export { a } from "/uxasset/externals/pkg/index.jsdbx";\n',
      );
    });

    test("rewrites when the clause carries other attributes too", () => {
      const result = transform(
        servicenowSeismicPlugin(),
        'import a from "pkg" with { external: "uxasset", type: "json" };\n',
      );
      expect(result.code).toBe(
        'import a from "/uxasset/externals/pkg/index.jsdbx";\n',
      );
    });

    test("leaves the rest of the module untouched", () => {
      const result = transform(
        servicenowSeismicPlugin(),
        'import a from "pkg" assert { external: "uxasset" };\nconst b = 1;\n',
      );
      expect(result.code).toBe(
        'import a from "/uxasset/externals/pkg/index.jsdbx";\nconst b = 1;\n',
      );
    });
  });

  describe("dynamic imports", () => {
    test("rewrites `with` options and drops the options argument", () => {
      const result = transform(
        servicenowSeismicPlugin(),
        'const m = await import("pkg", { with: { external: "uxasset" } });\n',
      );
      expect(result.code).toBe(
        'const m = await import("/uxasset/externals/pkg/index.jsdbx");\n',
      );
    });

    test("rewrites legacy `assert` options too", () => {
      const result = transform(
        servicenowSeismicPlugin(),
        'const m = await import("pkg", { assert: { external: "uxasset" } });\n',
      );
      expect(result.code).toBe(
        'const m = await import("/uxasset/externals/pkg/index.jsdbx");\n',
      );
    });

    test("rewrites a dynamic import nested inside a function", () => {
      const result = transform(
        servicenowSeismicPlugin(),
        'export const load = () =>\n  import("@servicenow/now-button", { with: { external: "uxasset" } });\n',
      );
      expect(result.code).toBe(
        'export const load = () =>\n  import("/uxasset/externals/@servicenow/now-button/index.jsdbx");\n',
      );
    });

    test("leaves a dynamic import without options alone", () => {
      expect(
        transform(
          servicenowSeismicPlugin(),
          'const m = await import("pkg");\n',
        ),
      ).toBeNull();
    });

    test("leaves a dynamic import with non-matching options alone", () => {
      expect(
        transform(
          servicenowSeismicPlugin(),
          'const m = await import("./d.json", { with: { type: "json" } });\n',
        ),
      ).toBeNull();
    });

    test("leaves a non-literal specifier alone", () => {
      expect(
        transform(
          servicenowSeismicPlugin(),
          'const m = await import(name, { with: { external: "uxasset" } });\n',
        ),
      ).toBeNull();
    });

    test("handles a static and a dynamic uxasset import in one module", () => {
      const result = transform(
        servicenowSeismicPlugin(),
        'import a from "s-pkg" assert { external: "uxasset" };\n' +
          'const b = await import("d-pkg", { with: { external: "uxasset" } });\n',
      );
      expect(result.code).toBe(
        'import a from "/uxasset/externals/s-pkg/index.jsdbx";\n' +
          'const b = await import("/uxasset/externals/d-pkg/index.jsdbx");\n',
      );
    });
  });

  describe("imports it must not claim", () => {
    test("leaves a uxasset *asset* import exactly as authored", () => {
      expect(
        transform(
          servicenowSeismicPlugin(),
          'import logo from "./logo.png" assert { type: "uxasset" };\n',
        ),
      ).toBeNull();
    });

    test("leaves a `with { type: json }` import completely alone", () => {
      expect(
        transform(
          servicenowSeismicPlugin(),
          'import d from "./data.json" with { type: "json" };\n',
        ),
      ).toBeNull();
    });

    test("leaves imports without attributes alone", () => {
      expect(
        transform(servicenowSeismicPlugin(), 'import a from "./local.js";\n'),
      ).toBeNull();
    });

    test("does not treat a non-matching attribute value as external", () => {
      expect(
        transform(
          servicenowSeismicPlugin(),
          'import a from "pkg" assert { external: "something-else" };\n',
        ),
      ).toBeNull();
    });

    test("does not touch an `assert` inside a comment", () => {
      expect(
        transform(
          servicenowSeismicPlugin(),
          'import d from "./data.json" /* assert */ with { type: "json" };\n',
        ),
      ).toBeNull();
    });

    test("skips ids the filter rejects", () => {
      expect(
        transform(
          servicenowSeismicPlugin(),
          'import a from "pkg" with { external: "uxasset" };\n',
          "/project/src/styles.css",
        ),
      ).toBeNull();
    });

    test("returns null rather than throwing on unparseable input", () => {
      expect(
        transform(
          servicenowSeismicPlugin(),
          'import a from "pkg" with { external: ;;; \n',
        ),
      ).toBeNull();
    });
  });

  describe("marking the rewritten path external", () => {
    test("externalizes anything under the uxasset externals prefix", () => {
      expect(
        resolveId(
          servicenowSeismicPlugin(),
          "/uxasset/externals/@servicenow/ui-core/index.jsdbx",
        ),
      ).toEqual({
        id: "/uxasset/externals/@servicenow/ui-core/index.jsdbx",
        external: true,
        resolvedBy: "seismic",
      });
    });

    test("ignores everything else", () => {
      expect(resolveId(servicenowSeismicPlugin(), "./local.js")).toBeNull();
      expect(resolveId(servicenowSeismicPlugin(), "lodash")).toBeNull();
    });

    test("the rewritten specifier is one this plugin then externalizes", () => {
      const result = transform(
        servicenowSeismicPlugin(),
        'import a from "pkg" assert { external: "uxasset" };\n',
      );
      const specifier = result.code.match(/"([^"]+)"/)![1];
      expect(resolveId(servicenowSeismicPlugin(), specifier)).toEqual({
        id: specifier,
        external: true,
        resolvedBy: "seismic",
      });
    });
  });

  describe("base public path", () => {
    test.each([
      ["/", "/uxasset/externals/pkg/index.jsdbx"],
      ["", "/uxasset/externals/pkg/index.jsdbx"],
      ["./", "/uxasset/externals/pkg/index.jsdbx"],
      ["/my/app/", "/my/app/uxasset/externals/pkg/index.jsdbx"],
      ["/my/app", "/my/app/uxasset/externals/pkg/index.jsdbx"],
      [
        "https://cdn.example.com/",
        "https://cdn.example.com/uxasset/externals/pkg/index.jsdbx",
      ],
    ])("withBase(%p) -> %p", (base, expected) => {
      expect(withBase(base, `${UXASSET_EXTERNAL_PREFIX}pkg/index.jsdbx`)).toBe(
        expected,
      );
    });

    test("prefixes base in a build", () => {
      const plugin = servicenowSeismicPlugin();
      configure(plugin, "build", "/my/app/");
      const result = transform(
        plugin,
        'import a from "pkg" assert { external: "uxasset" };\n',
      );
      expect(result.code).toBe(
        'import a from "/my/app/uxasset/externals/pkg/index.jsdbx";\n',
      );
    });

    test("does NOT prefix base in dev -- vite's import-analysis adds it, and doing both double-prefixes", () => {
      const plugin = servicenowSeismicPlugin();
      configure(plugin, "serve", "/my/app/");
      const result = transform(
        plugin,
        'import a from "pkg" assert { external: "uxasset" };\n',
      );
      expect(result.code).toBe(
        'import a from "/uxasset/externals/pkg/index.jsdbx";\n',
      );
    });

    test("prefixes base on a dynamic import in a build", () => {
      const plugin = servicenowSeismicPlugin();
      configure(plugin, "build", "/my/app/");
      const result = transform(
        plugin,
        'const m = await import("pkg", { with: { external: "uxasset" } });\n',
      );
      expect(result.code).toBe(
        'const m = await import("/my/app/uxasset/externals/pkg/index.jsdbx");\n',
      );
    });

    test("externalizes the base-prefixed path", () => {
      const plugin = servicenowSeismicPlugin();
      configure(plugin, "build", "/my/app/");
      expect(
        resolveId(plugin, "/my/app/uxasset/externals/pkg/index.jsdbx"),
      ).toMatchObject({ external: true, resolvedBy: "seismic" });
      expect(
        resolveId(plugin, "/uxasset/externals/pkg/index.jsdbx"),
      ).toBeNull();
    });

    test("still ignores unrelated ids under a base", () => {
      const plugin = servicenowSeismicPlugin();
      configure(plugin, "build", "/my/app/");
      expect(resolveId(plugin, "/my/app/src/local.js")).toBeNull();
    });
  });

  describe("parity with the rollup seismic plugin", () => {
    const rollupResolve = (
      source: string,
      attributes: Record<string, string>,
    ) =>
      (rollupSeismic() as PluginRecord).resolveId.call({}, source, undefined, {
        attributes,
        isEntry: false,
      });

    test.each([
      "@servicenow/ui-core",
      "@devsnc/library-uxf",
      "lodash",
      "sn-foobar-baz",
    ])(
      "produces the same externals path as the rollup plugin for %s",
      async (specifier) => {
        const fromRollup = await rollupResolve(specifier, {
          external: "uxasset",
        });
        expect(`${UXASSET_EXTERNAL_PREFIX}${specifier}/index.jsdbx`).toBe(
          (fromRollup as { id: string }).id,
        );
      },
    );

    test("agrees on the externals prefix", async () => {
      const fromRollup = await rollupResolve("pkg", { external: "uxasset" });
      expect((fromRollup as { id: string }).id).toContain(
        UXASSET_EXTERNAL_PREFIX,
      );
    });

    test("both mark an already-prefixed path external", async () => {
      const path = "/uxasset/externals/pkg/index.jsdbx";
      const fromRollup = await rollupResolve(path, {});
      expect(fromRollup).toMatchObject({ id: path, external: true });
      expect(resolveId(servicenowSeismicPlugin(), path)).toMatchObject({
        id: path,
        external: true,
      });
    });
  });

  describe("isolateExternalImports (renderChunk)", () => {
    const PREFIX = UXASSET_EXTERNAL_PREFIX;

    test("hoists consecutive static imports to the top", async () => {
      const code =
        'import "/uxasset/externals/a/index.jsdbx";import "/uxasset/externals/b/index.jsdbx";';
      const result = await isolateExternalImports(code, PREFIX);
      expect(result!.code).toBe(
        'import "/uxasset/externals/a/index.jsdbx";\nimport "/uxasset/externals/b/index.jsdbx";\n',
      );
    });

    test("hoists a static import out of inline position to the top", async () => {
      const code = 'const x = 1;import "/uxasset/externals/a/index.jsdbx";\n';
      const result = await isolateExternalImports(code, PREFIX);
      expect(result!.code).toBe(
        'import "/uxasset/externals/a/index.jsdbx";\nconst x = 1;\n',
      );
    });

    test("isolates a dynamic import onto its own line", async () => {
      const code =
        'const a = 1;const b = await import("/uxasset/externals/pkg/index.jsdbx");const c = 2;';
      const result = await isolateExternalImports(code, PREFIX);
      expect(result!.code).toBe(
        'const a = 1;\nconst b = await import("/uxasset/externals/pkg/index.jsdbx");\nconst c = 2;',
      );
    });

    test("hoists static import and isolates dynamic import", async () => {
      const code =
        'import "/uxasset/externals/a/index.jsdbx";const b = await import("/uxasset/externals/b/index.jsdbx");';
      const result = await isolateExternalImports(code, PREFIX);
      expect(result!.code).toBe(
        'import "/uxasset/externals/a/index.jsdbx";\nconst b = await import("/uxasset/externals/b/index.jsdbx");',
      );
    });

    test("still hoists even when imports are already on their own lines", async () => {
      const code =
        'import "/uxasset/externals/a/index.jsdbx";\nimport "/uxasset/externals/b/index.jsdbx";\n';
      const result = await isolateExternalImports(code, PREFIX);
      expect(result!.code).toBe(
        'import "/uxasset/externals/a/index.jsdbx";\nimport "/uxasset/externals/b/index.jsdbx";\n',
      );
    });

    test("returns null when the prefix is not present", async () => {
      expect(
        await isolateExternalImports('import "lodash";\n', PREFIX),
      ).toBeNull();
    });

    test("hoists three consecutive static imports to the top", async () => {
      const code =
        'import "/uxasset/externals/a/index.jsdbx";import "/uxasset/externals/b/index.jsdbx";import "/uxasset/externals/c/index.jsdbx";';
      const result = await isolateExternalImports(code, PREFIX);
      expect(result!.code).toBe(
        'import "/uxasset/externals/a/index.jsdbx";\nimport "/uxasset/externals/b/index.jsdbx";\nimport "/uxasset/externals/c/index.jsdbx";\n',
      );
    });

    test("produces a sourcemap", async () => {
      const code =
        'import "/uxasset/externals/a/index.jsdbx";import "/uxasset/externals/b/index.jsdbx";';
      const result = await isolateExternalImports(code, PREFIX);
      expect(result!.map).toBeDefined();
    });

    test("remapping after hoisting preserves all original sources", async () => {
      const remapping = (await import("@jridgewell/remapping")).default;

      // Simulate a minified chunk: two external imports followed by app code,
      // where the original sourcemap references three different source files.
      // The external imports map to node_modules sources; the app code maps
      // to the user's source file.
      const code =
        'import "/uxasset/externals/a/index.jsdbx";import "/uxasset/externals/b/index.jsdbx";var x=1;';

      // Original sourcemap with 3 sources — one per statement.
      // Mappings: line 1 has three segments mapping to source 0, 1, and 2.
      const originalMap = {
        version: 3 as const,
        sources: [
          "node_modules/a/index.js",
          "node_modules/b/index.js",
          "src/app.ts",
        ],
        sourcesContent: ["// a", "// b", "var x = 1;"],
        // Three segments on one line: col 0 → src 0, col 42 → src 1, col 84 → src 2
        mappings: "AAAA,2CCAA,2CCAA",
        names: [] as string[],
      };

      const result = await isolateExternalImports(code, PREFIX);
      expect(result).not.toBeNull();

      const composed = remapping(
        [result!.map as never, originalMap as never],
        () => null,
      );

      // All three original sources must survive the composition.
      expect(composed.sources).toEqual(
        expect.arrayContaining(originalMap.sources),
      );
      expect(composed.sources).toHaveLength(originalMap.sources.length);

      // sourcesContent must also be preserved.
      expect(composed.sourcesContent).toEqual(
        expect.arrayContaining(originalMap.sourcesContent),
      );
    });

    test("inserts a newline after a block comment at the hoist target", async () => {
      const code =
        '/*__ESM_BODY_START__*/window.process={};import "/uxasset/externals/a/index.jsdbx";';
      const result = await isolateExternalImports(code, PREFIX);
      expect(result!.code).toBe(
        'import "/uxasset/externals/a/index.jsdbx";\n/*__ESM_BODY_START__*/\nwindow.process={};',
      );
    });

    test("works with a base-prefixed path", async () => {
      const prefix = "/my/app/uxasset/externals/";
      const code =
        'import "/my/app/uxasset/externals/a/index.jsdbx";import "/my/app/uxasset/externals/b/index.jsdbx";';
      const result = await isolateExternalImports(code, prefix);
      expect(result!.code).toBe(
        'import "/my/app/uxasset/externals/a/index.jsdbx";\nimport "/my/app/uxasset/externals/b/index.jsdbx";\n',
      );
    });
  });
});
